using StudentPortal.Models;
using StudentPortal.Data;
// =====================================================================
// SeedData.cs - Dữ liệu mẫu: 200 sinh viên, 22 lớp, 206 tài khoản
// Cùng bộ dữ liệu với QuanLySinhVien_SQLServer.sql
//
// GIẢ ĐỊNH (sửa cho khớp project của bạn nếu khác):
//   - DbContext : ApplicationDbContext, có DbSet: Khoa, KhoaHoc, Lop, SinhVien,
//                 NhatKyThaoTac, LichSuHoSoSinhVien
//   - Entity    : Khoa, KhoaHoc, Lop, SinhVien, NhatKyThaoTac, LichSuHoSoSinhVien
//                 (tên thuộc tính đúng theo cột trong ERD)
//   - User      : ApplicationUser : IdentityUser, thêm HoTen, MaSV, MaKhoaPhuTrach,
//                 TrangThaiTaiKhoan (int), LanDangNhapDauTien (DateTime?)
//   - SinhVien.NgaySinh là DateTime (nếu bạn dùng DateOnly: đổi DateTime.Parse -> DateOnly.Parse)
//
// Cách dùng (Program.cs, sau app.Build()):
//   await SeedData.InitializeAsync(app.Services);
//
// Quy ước: GioiTinh 0=Nữ 1=Nam | TrangThai 0=Đang học 1=Bảo lưu 2=Thôi học 3=Đã tốt nghiệp
//          TrangThaiTaiKhoan 0=Khóa 1=Hoạt động | LichSu.Loai 1=SĐT 2=Email 3=Địa chỉ 4=Trạng thái
// Mật khẩu mẫu: admin = Admin@123 | gv.* = GiaoVu@123 | sinh viên (UserName=MaSV) = Student@123
// Mật khẩu được băm bằng UserManager lúc chạy nên luôn đúng với cấu hình Identity của bạn.
// =====================================================================
using System.Globalization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

public static class SeedData
{
    private static DateTime T(string s) => DateTime.ParseExact(s, "yyyy-MM-ddTHH:mm:ss", CultureInfo.InvariantCulture);
    private static DateTime? Tn(string? s) => s is null ? null : T(s);

    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();
        var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();

        await db.Database.MigrateAsync();
        if (await db.SinhVien.AnyAsync()) return; // đã có dữ liệu thì bỏ qua

        // ---------- Danh mục ----------
        db.Khoa.AddRange(
            new Khoa { MaKhoa = "CNTT", TenKhoa = "Công nghệ thông tin", DaXoa = false },
            new Khoa { MaKhoa = "QTKD", TenKhoa = "Quản trị kinh doanh", DaXoa = false },
            new Khoa { MaKhoa = "KT", TenKhoa = "Kế toán", DaXoa = false },
            new Khoa { MaKhoa = "NNA", TenKhoa = "Ngôn ngữ Anh", DaXoa = false },
            new Khoa { MaKhoa = "LUAT", TenKhoa = "Luật", DaXoa = false });
        db.KhoaHoc.AddRange(            new KhoaHoc { MaKhoaHoc = "K22", NamNhapHoc = 2022, DaXoa = false },
            new KhoaHoc { MaKhoaHoc = "K23", NamNhapHoc = 2023, DaXoa = false },
            new KhoaHoc { MaKhoaHoc = "K24", NamNhapHoc = 2024, DaXoa = false },
            new KhoaHoc { MaKhoaHoc = "K25", NamNhapHoc = 2025, DaXoa = false },
            new KhoaHoc { MaKhoaHoc = "K26", NamNhapHoc = 2026, DaXoa = false });
        db.Lop.AddRange(            new Lop { MaLop = "CNTT-K22A", TenLop = "Công nghệ thông tin K22A", MaKhoa = "CNTT", MaKhoaHoc = "K22", DaXoa = false },
            new Lop { MaLop = "CNTT-K23A", TenLop = "Công nghệ thông tin K23A", MaKhoa = "CNTT", MaKhoaHoc = "K23", DaXoa = false },
            new Lop { MaLop = "CNTT-K24A", TenLop = "Công nghệ thông tin K24A", MaKhoa = "CNTT", MaKhoaHoc = "K24", DaXoa = false },
            new Lop { MaLop = "CNTT-K25A", TenLop = "Công nghệ thông tin K25A", MaKhoa = "CNTT", MaKhoaHoc = "K25", DaXoa = false },
            new Lop { MaLop = "CNTT-K26A", TenLop = "Công nghệ thông tin K26A", MaKhoa = "CNTT", MaKhoaHoc = "K26", DaXoa = false },
            new Lop { MaLop = "QTKD-K23A", TenLop = "Quản trị kinh doanh K23A", MaKhoa = "QTKD", MaKhoaHoc = "K23", DaXoa = false },
            new Lop { MaLop = "QTKD-K24A", TenLop = "Quản trị kinh doanh K24A", MaKhoa = "QTKD", MaKhoaHoc = "K24", DaXoa = false },
            new Lop { MaLop = "QTKD-K25A", TenLop = "Quản trị kinh doanh K25A", MaKhoa = "QTKD", MaKhoaHoc = "K25", DaXoa = false },
            new Lop { MaLop = "QTKD-K26A", TenLop = "Quản trị kinh doanh K26A", MaKhoa = "QTKD", MaKhoaHoc = "K26", DaXoa = false },
            new Lop { MaLop = "KT-K22A", TenLop = "Kế toán K22A", MaKhoa = "KT", MaKhoaHoc = "K22", DaXoa = false },
            new Lop { MaLop = "KT-K23A", TenLop = "Kế toán K23A", MaKhoa = "KT", MaKhoaHoc = "K23", DaXoa = false },
            new Lop { MaLop = "KT-K24A", TenLop = "Kế toán K24A", MaKhoa = "KT", MaKhoaHoc = "K24", DaXoa = false },
            new Lop { MaLop = "KT-K25A", TenLop = "Kế toán K25A", MaKhoa = "KT", MaKhoaHoc = "K25", DaXoa = false },
            new Lop { MaLop = "KT-K26A", TenLop = "Kế toán K26A", MaKhoa = "KT", MaKhoaHoc = "K26", DaXoa = false },
            new Lop { MaLop = "NNA-K23A", TenLop = "Ngôn ngữ Anh K23A", MaKhoa = "NNA", MaKhoaHoc = "K23", DaXoa = false },
            new Lop { MaLop = "NNA-K24A", TenLop = "Ngôn ngữ Anh K24A", MaKhoa = "NNA", MaKhoaHoc = "K24", DaXoa = false },
            new Lop { MaLop = "NNA-K25A", TenLop = "Ngôn ngữ Anh K25A", MaKhoa = "NNA", MaKhoaHoc = "K25", DaXoa = false },
            new Lop { MaLop = "NNA-K26A", TenLop = "Ngôn ngữ Anh K26A", MaKhoa = "NNA", MaKhoaHoc = "K26", DaXoa = false },
            new Lop { MaLop = "LUAT-K23A", TenLop = "Luật K23A", MaKhoa = "LUAT", MaKhoaHoc = "K23", DaXoa = false },
            new Lop { MaLop = "LUAT-K24A", TenLop = "Luật K24A", MaKhoa = "LUAT", MaKhoaHoc = "K24", DaXoa = false },
            new Lop { MaLop = "LUAT-K25A", TenLop = "Luật K25A", MaKhoa = "LUAT", MaKhoaHoc = "K25", DaXoa = false },
            new Lop { MaLop = "LUAT-K26A", TenLop = "Luật K26A", MaKhoa = "LUAT", MaKhoaHoc = "K26", DaXoa = false });
        await db.SaveChangesAsync();
        // ---------- Sinh viên ----------
        foreach (var r in SinhVienRows)
        {
            db.SinhVien.Add(new SinhVien
            {
                MaSV = r.MaSV, HoTen = r.HoTen, NgaySinh = DateTime.Parse(r.NgaySinh, CultureInfo.InvariantCulture),
                GioiTinh = r.GioiTinh, MaLop = r.MaLop, SDT = r.Sdt, Email = r.Email, DiaChi = r.DiaChi,
                TrangThai = r.TrangThai, DaXoa = r.DaXoa, NgayXoa = Tn(r.NgayXoa), NguoiXoa = r.NguoiXoa, LyDoXoa = r.LyDoXoa,
                NgayTao = T(r.NgayTao), NgayCapNhat = T(r.NgayCapNhat)
            });
        }
        await db.SaveChangesAsync();

        // ---------- Vai trò ----------
        foreach (var role in new[] { "Admin", "GiaoVu", "SinhVien" })
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));

        // ---------- Tài khoản ----------
        foreach (var a in TaiKhoanRows)
        {
            var user = new ApplicationUser
            {
                UserName = a.UserName, Email = a.Email, EmailConfirmed = true,
                PhoneNumber = a.Phone, HoTen = a.HoTen, MaSV = a.MaSV, MaKhoaPhuTrach = a.MaKhoaPhuTrach,
                TrangThaiTaiKhoan = a.HoatDong ? 1 : 0, LanDangNhapDauTien = Tn(a.LanDauDangNhap),
                LockoutEnabled = true,
                LockoutEnd = a.HoatDong ? null : new DateTimeOffset(2099, 1, 1, 0, 0, 0, TimeSpan.Zero)
            };
            var pw = a.Role switch { "Admin" => "Admin@123", "GiaoVu" => "GiaoVu@123", _ => "Student@123" };
            var result = await userManager.CreateAsync(user, pw);
            if (!result.Succeeded)
                throw new InvalidOperationException($"Seed tài khoản {a.UserName} lỗi: " + string.Join("; ", result.Errors.Select(e => e.Description)));
            await userManager.AddToRoleAsync(user, a.Role);
        }

        // ---------- Lịch sử hồ sơ & nhật ký ----------
        foreach (var h in LichSuRows)
            db.LichSuHoSoSinhVien.Add(new LichSuHoSoSinhVien
            {
                MaSV = h.MaSV, Loai = h.Loai, GiaTriCu = h.Cu, GiaTriMoi = h.Moi,
                LyDo = h.LyDo, NguoiThucHien = h.Nguoi, ThoiDiem = T(h.ThoiDiem)
            });
        foreach (var n in NhatKyRows)
            db.NhatKyThaoTac.Add(new NhatKyThaoTac
            {
                ThoiDiem = T(n.ThoiDiem), Username = n.Username, HanhDong = n.HanhDong,
                DoiTuongLoai = n.Loai, DoiTuongMa = n.Ma
            });
        await db.SaveChangesAsync();
    }

    // ===================== DỮ LIỆU =====================
    private record SvRow(string MaSV, string HoTen, string NgaySinh, int GioiTinh, string MaLop, string Sdt, string Email,
        string DiaChi, int TrangThai, bool DaXoa, string? NgayXoa, string? NguoiXoa, string? LyDoXoa, string NgayTao, string NgayCapNhat);
    private record TkRow(string UserName, string HoTen, string Email, string Phone, string? MaSV, string? MaKhoaPhuTrach,
        string Role, bool HoatDong, string? LanDauDangNhap);
    private record LsRow(string MaSV, int Loai, string Cu, string Moi, string LyDo, string Nguoi, string ThoiDiem);
    private record NkRow(string ThoiDiem, string Username, string HanhDong, string Loai, string Ma);

